import { useId, useRef, type KeyboardEvent } from "react";
import "./SegmentedControl.css";

export interface SegmentedOption<T extends string = string> {
  value: T;
  label: string;
}

export interface SegmentedControlProps<T extends string = string> {
  label: string;
  options: readonly SegmentedOption<T>[];
  value: T;
  onChange: (value: T) => void;
}

/** Index to move to for a navigation key, or -1 if the key is not a navigation key. */
function targetIndex(key: string, current: number, count: number): number {
  switch (key) {
    case "ArrowRight":
    case "ArrowDown":
      return (current + 1) % count;
    case "ArrowLeft":
    case "ArrowUp":
      return (current - 1 + count) % count;
    case "Home":
      return 0;
    case "End":
      return count - 1;
    default:
      return -1;
  }
}

export function SegmentedControl<T extends string = string>({
  label,
  options,
  value,
  onChange,
}: SegmentedControlProps<T>) {
  const labelId = useId();
  const buttons = useRef<(HTMLButtonElement | null)[]>([]);

  const selectedIndex = options.findIndex((option) => option.value === value);
  // Roving tabindex: only one radio sits in the Tab order.
  const tabStop = selectedIndex >= 0 ? selectedIndex : 0;

  function handleKeyDown(event: KeyboardEvent<HTMLButtonElement>, index: number) {
    const next = targetIndex(event.key, index, options.length);
    if (next < 0) {
      return;
    }
    event.preventDefault();
    buttons.current[next]?.focus();
    const option = options[next];
    if (option.value !== value) {
      onChange(option.value);
    }
  }

  return (
    <div className="segmented">
      <span className="segmented-label" id={labelId}>
        {label}
      </span>
      <div role="radiogroup" aria-labelledby={labelId} className="segmented-track">
        {options.map((option, index) => {
          const checked = index === selectedIndex;
          return (
            <button
              key={option.value}
              ref={(element) => {
                buttons.current[index] = element;
              }}
              type="button"
              role="radio"
              aria-checked={checked}
              tabIndex={index === tabStop ? 0 : -1}
              className="segmented-option"
              onClick={() => onChange(option.value)}
              onKeyDown={(event) => handleKeyDown(event, index)}
            >
              {option.label}
            </button>
          );
        })}
      </div>
    </div>
  );
}
